import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"The release process (SOP)","description":"","frontmatter":{},"headers":[],"relativePath":"release/process.md","filePath":"release/process.md"}'),i={name:"release/process.md"};function r(n,e,l,d,c,p){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="the-release-process-sop" tabindex="-1">The release process (SOP) <a class="header-anchor" href="#the-release-process-sop" aria-label="Permalink to &quot;The release process (SOP)&quot;">​</a></h1><p>The exact sequence a release walks. Every step has a gate; a failed gate stops the release.</p><h2 id="_0-pre-flight" tabindex="-1">0. Pre-flight <a class="header-anchor" href="#_0-pre-flight" aria-label="Permalink to &quot;0. Pre-flight&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git fetch &amp;&amp; git status        (clean tree, correct branch)</span></span>
<span class="line"><span>git tag --list &#39;v*&#39;           (the new tag does not exist yet)</span></span>
<span class="line"><span>git config user.name / user.email   (author = cubestudio-dev &lt;cubestudio@qq.com&gt;)</span></span></code></pre></div><h2 id="_1-build" tabindex="-1">1. Build <a class="header-anchor" href="#_1-build" aria-label="Permalink to &quot;1. Build&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make clean &amp;&amp; make -j$(nproc) all</span></span></code></pre></div><p>Gate: 0 errors 0 warnings (<code>-Wall -Wextra -Werror</code> is in the flags) <strong>on BOTH the local toolchain and the GitHub Actions runner</strong> - the 2.0.0 release shipped source that compiled locally but not on CI (the tui_core.c port-constraint P0; see KNOWN_ISSUES.md). CI green is a hard release gate, not a nice-to-have. Outputs: <code>build/opencube.iso</code>, <code>dist/OpenCubeOS-&lt;ver&gt;-src.zip</code>, <code>dist/OpenCubeOS-&lt;ver&gt;-update.tar.gz</code>.</p><h2 id="_2-reproducibility" tabindex="-1">2. Reproducibility <a class="header-anchor" href="#_2-reproducibility" aria-label="Permalink to &quot;2. Reproducibility&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make reproducible-check</span></span></code></pre></div><p>Gate: <code>PASS - ELF byte-identical across two clean builds</code>.</p><h2 id="_3-boot-gates" tabindex="-1">3. Boot gates <a class="header-anchor" href="#_3-boot-gates" aria-label="Permalink to &quot;3. Boot gates&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make run-bios      (banner + ring-3 ush&gt; + boot complete)</span></span>
<span class="line"><span>make run-uefi      (same, through OVMF)</span></span></code></pre></div><p>The default boot lands in the ring-3 <code>ush&gt;</code> shell; <code>oc&gt;</code> appears after <code>exit</code> (or on launcher failure - the recovery posture).</p><h2 id="_4-deep-test-gates-on-the-built-iso" tabindex="-1">4. Deep test gates (on the built ISO) <a class="header-anchor" href="#_4-deep-test-gates-on-the-built-iso" aria-label="Permalink to &quot;4. Deep test gates (on the built ISO)&quot;">​</a></h2><p>The 2.1.0 verification matrix - every suite drives a real QEMU boot over the serial console; paste the real outputs (skip counts included) into the release evidence:</p><table tabindex="0"><thead><tr><th>Gate</th><th>Command</th><th>What it proves</th></tr></thead><tbody><tr><td>Host unit tests</td><td><code>make test</code></td><td>17 harnesses PASS (+2 SKIP-FIXTURE without openssl fixtures - declare the skips)</td></tr><tr><td>Watchdog/logging/health E2E</td><td><code>tools/wp12_watchdog_logging_e2e.py</code></td><td>14 scenarios (S1-S14 incl. Intel TCO real reset)</td></tr><tr><td>TUI command surface E2E</td><td><code>tools/wp10_tui_e2e.py</code></td><td>the L0 TUI commands on the v2 boot flow</td></tr><tr><td>Chinese console E2E</td><td><code>tools/wp10_chinese_e2e.py</code></td><td>the CJK layer end to end</td></tr><tr><td>TUI desktop apps E2E</td><td><code>tools/wp10_tuiqa_apps_e2e.py</code></td><td>the desktop five-app flow from <code>ush&gt;</code></td></tr><tr><td>Native desktop E2E</td><td><code>tools/wp10_native_e2e.py</code></td><td>the native editor/file-manager flows</td></tr><tr><td>L1 per-app record</td><td>run every <code>l1apps/</code> program via <code>run</code> from ush</td><td>ush + each embedded program actually executes (2.1.0 addition; see docs/dev/e2e-suites.md)</td></tr></tbody></table><h2 id="_5-tag-release" tabindex="-1">5. Tag + Release <a class="header-anchor" href="#_5-tag-release" aria-label="Permalink to &quot;5. Tag + Release&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git tag -a v&lt;version&gt;          # ONLY on a CI-green commit</span></span>
<span class="line"><span>git push origin main --tags</span></span></code></pre></div><p>GitHub Release from the tag with the note containing: change summary, new interfaces, known issues, the three SHA256s. Attach the three assets. The release script (<code>tools/build_release.sh --deep</code>) automates manifest + note + upload.</p><p><strong>Release gate (2.1.0): the tag must point at the CI-green commit. Never tag a red commit.</strong></p><h2 id="_6-website-wiki" tabindex="-1">6. Website + wiki <a class="header-anchor" href="#_6-website-wiki" aria-label="Permalink to &quot;6. Website + wiki&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tools/update_website.sh    (versions/hashes/downloads on the site)</span></span>
<span class="line"><span>tools/sync_wiki.sh         (docs/ -&gt; the GitHub Wiki)</span></span></code></pre></div><p>Gate: the live site shows the new version, the three SHA256s match the Release, downloads resolve HTTP 200 and hash-verify, and the site stats block is REGENERATED from <code>docs/data/*.json</code> (never copied from a stale block - the 2.0.0 site shipped a stale 130,011 line count that way).</p><h2 id="_7-private-mirror" tabindex="-1">7. Private mirror <a class="header-anchor" href="#_7-private-mirror" aria-label="Permalink to &quot;7. Private mirror&quot;">​</a></h2><p>Copy the three assets + release note + the mirrored website files into the private repository (<code>oc-os/</code> tree + repo-level audit documents); push. Gate: <code>git ls-remote</code> on both repos shows the expected HEADs.</p><h2 id="_8-the-12-point-check" tabindex="-1">8. The 12-point check <a class="header-anchor" href="#_8-the-12-point-check" aria-label="Permalink to &quot;8. The 12-point check&quot;">​</a></h2><ol><li>Both repos&#39; remote HEADs match local.</li><li>The tag exists on the public repo and points at a CI-green commit.</li><li>Author identity on every release commit.</li><li>gh-pages updated (live site serves the new version).</li><li>update.json: version + build + package_sha256 (both copies - website/ top level AND website/public/ - byte-identical).</li><li>Three-way asset hashes: local = Release API digest = live download.</li><li>Website numbers (commands/interfaces/lines) match <code>docs/data/*.json</code> (regenerated, not copied).</li><li>The gates in step 4 all green (paste the outputs, skip counts declared).</li><li>Token hygiene (only last-4 ever shown).</li><li>Whole-repo number consistency: 251 command homes (99+133+19) / 17 categories / 158 L1SVC ops / 54 syscalls / the current stats.json line count (recomputed every release; never a stale figure).</li><li>Private mirror complete.</li><li>CI green on the release commit (and on the tagged commit).</li></ol><h2 id="_9-report" tabindex="-1">9. Report <a class="header-anchor" href="#_9-report" aria-label="Permalink to &quot;9. Report&quot;">​</a></h2><p>The delivery report quotes: build evidence (local + CI), all gate outputs, push outputs (public + private), the Release URL, the site URL, the three SHA256s, and the honest-deviation list.</p>`,29)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
